begin;
create temp table q5_checks(label text,pass boolean) on commit drop;
create function pg_temp.check_proposal(label text,p jsonb,expected boolean) returns void language plpgsql as $$declare ok boolean:=true;begin begin perform coach_private.validate_proposal(p);exception when others then ok:=false;end;insert into q5_checks values(label,ok=expected);if ok<>expected then raise exception 'check_failed: %',label;end if;end$$;
